.lf-wrap{max-width:760px;margin:0 auto;padding:20px 20px 60px;font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen-Sans, Ubuntu, Cantarell, 'Helvetica Neue', sans-serif;box-sizing:border-box;}
.lf-wrap *{box-sizing:border-box;}
.lf-back{display:inline-block;font-size:13px;letter-spacing:.5px;color:#1B4332;text-decoration:none;margin-bottom:24px;}
.lf-eyebrow{font-size:12px;letter-spacing:2px;color:#8a988a;margin-bottom:14px;text-align:center;}
.lf-h1{font-size:36px;color:#1B4332;margin:0 0 6px;text-align:center;font-weight:800;}
.lf-h1-sub{font-size:13px;letter-spacing:1.5px;color:#7a8a7a;text-align:center;margin-bottom:30px;}
.lf-h2{font-size:21px;color:#1a1a1a;font-weight:700;margin:0 0 22px;text-align:justify;}
.lf-text{color:#3a3a3a;line-height:1.85;font-size:15.5px;margin:0 0 14px;text-align:justify;}
.lf-step{display:flex;gap:22px;position:relative;padding-bottom:44px;}
.lf-step-num-col{flex:0 0 46px;display:flex;flex-direction:column;align-items:center;}
.lf-step-num{width:46px;height:46px;border-radius:50%;background:#1B4332;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:15px;flex-shrink:0;}
.lf-step-line{width:2px;background:#dbe3db;flex:1;margin-top:8px;}
.lf-step-card{flex:1;background:#fff;border:1px solid #eae7e0;border-radius:14px;padding:26px 28px;box-shadow:0 2px 10px rgba(27,67,50,0.05);min-width:0;}
.lf-step-tag{font-size:11px;letter-spacing:1.5px;color:#9aa89a;margin-bottom:8px;}
.lf-step-title{margin:0 0 14px;color:#1B4332;font-size:21px;font-weight:700;text-align:justify;}
.lf-quote{border-left:3px solid #1B4332;margin:16px 0 0;padding:2px 0 2px 18px;font-style:italic;color:#1B4332;font-size:15.5px;text-align:justify;}
.lf-sub{margin-top:16px;background:#FAF8F4;border-radius:10px;padding:16px 20px;}
.lf-sub-title{font-weight:700;color:#1B4332;font-size:14px;margin-bottom:6px;}
.lf-sub-text{font-size:14px;margin:0;color:#444;}
.lf-closing{text-align:center;padding-top:10px;}
.lf-closing h3{color:#1B4332;font-size:22px;margin-bottom:16px;}
.lf-closing p{color:#3a3a3a;line-height:1.85;font-size:15.5px;text-align:justify;margin-bottom:22px;}
.lf-cta{display:inline-block;background:#1B4332;color:#fff;padding:14px 32px;border-radius:30px;font-size:14px;letter-spacing:1px;text-decoration:none;}
@media (max-width:520px){
  .lf-step{gap:12px;}
  .lf-step-num-col{flex:0 0 34px;}
  .lf-step-num{width:34px;height:34px;font-size:12px;}
  .lf-step-card{padding:18px 16px;}
  .lf-h1{font-size:28px;}
}

