.lf-step-card{flex:1;background:#fff;border:1px solid #eae7e0;border-radius:14px;padding:26px 28px;box-shadow:0 2px 10px rgba(27,67,50,0.05);min-width:0;}
.lf-step-tag{font-size:11px;letter-spacing:1.5px;color:#9aa89a;margin-bottom:8px;}
.lf-step-title{margin:0 0 14px;color:#1B4332;font-size:21px;font-weight:700;text-align:justify;}
.lf-quote{border-left:3px solid #1B4332;margin:16px 0 0;padding:2px 0 2px 18px;font-style:italic;color:#1B4332;font-size:15.5px;text-align:justify;}
.lf-sub{margin-top:16px;background:#FAF8F4;border-radius:10px;padding:16px 20px;}
.lf-sub-title{font-weight:700;color:#1B4332;font-size:14px;margin-bottom:6px;}
.lf-sub-text{font-size:14px;margin:0;color:#444;}
.lf-closing{text-align:center;padding-top:10px;}
.lf-closing h3{color:#1B4332;font-size:22px;margin-bottom:16px;}
.lf-closing p{color:#3a3a3a;line-height:1.85;font-size:15.5px;text-align:justify;margin-bottom:22px;}
.lf-cta{display:inline-block;background:#1B4332;color:#fff;padding:14px 32px;border-radius:30px;font-size:14px;letter-spacing:1px;text-decoration:none;}
@media (max-width:520px){
