.lpl-wrap .lpl-rs-handle{position:absolute;top:50%;width:18px;height:18px;background:#1b4332;border:3px solid #fff;box-shadow:0 0 0 1px #1b4332;border-radius:50%;transform:translate(-50%,-50%);cursor:grab;touch-action:none;z-index:2;}
