.lpl-wrap .lpl-more-btn{background:#1b4332;color:#fff;border:none;padding:12px 18px;border-radius:8px;font-weight:700;font-size:14px;cursor:pointer;font-family:inherit;white-space:nowrap;}
.lpl-wrap .lpl-more-btn:hover{background:#3a844c;}
.lpl-wrap .lpl-more-panel{margin-top:14px;background:#fff;border:1px solid #e2e2e2;border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:14px;}
