.lpl-wrap .lpl-sort-wrap{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:24px;}
.lpl-wrap .lpl-sort-label{font-weight:700;font-size:13px;letter-spacing:.5px;color:#0d141a;margin-right:4px;}
.lpl-wrap .lpl-sort-btn{background:#fff;color:#1b4332;border:1.5px solid #1b4332;padding:8px 14px;border-radius:20px;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;}
.lpl-wrap .lpl-sort-btn:hover{background:#eaf1ec;}
.lpl-wrap .lpl-sort-btn.active{background:#1b4332;color:#fff;}
